dashboard.definition:
{
  "title": "Wazuh - AWS - Overview dashboard",
  "description": "AWS - Overview dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_01": {
      "type": "ds.search",
      "name": "Top 5 sources (overview)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" | eval f1='event.provider' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"event.provider\", metric as \"Count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "Top AWS accounts (overview)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" | eval f1='cloud.account.id' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"cloud.account.id\", metric as \"Count\""
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Top 5 actions (overview)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" | eval f1='event.action' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"event.action\", metric as \"Count\""
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Top 5 AWS regions (overview)",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" | eval f1='cloud.region' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"cloud.region\", metric as \"Count\""
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Events by source over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" | eval f1='event.provider' | timechart useother=f usenull=f limit=5 count by f1"
      }
    },
    "ds_06": {
      "type": "ds.search",
      "name": "Top actions over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"aws*\" | eval f1='event.action' | timechart useother=f usenull=f limit=5 count by f1"
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.pie",
      "title": "Top 5 sources (overview)",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_02": {
      "type": "splunk.pie",
      "title": "Top AWS accounts (overview)",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_03": {
      "type": "splunk.pie",
      "title": "Top 5 actions (overview)",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_04": {
      "type": "splunk.pie",
      "title": "Top 5 AWS regions (overview)",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_05": {
      "type": "splunk.area",
      "title": "Events by source over time",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_06": {
      "type": "splunk.area",
      "title": "Top actions over time",
      "dataSources": {
        "primary": "ds_06"
      },
      "options": {
        "stackMode": "stacked"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 436,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 300,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 600,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 900,
          "y": 0,
          "w": 296,
          "h": 176
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 0,
          "y": 180,
          "w": 596,
          "h": 236
        }
      },
      {
        "item": "viz_06",
        "type": "block",
        "position": {
          "x": 600,
          "y": 180,
          "w": 596,
          "h": 236
        }
      }
    ]
  }
}
